// === GENERAR EL CÓDIGO ===
const allExams = [...exam3, ...exam4, ...exam5];
let output = '\n// =============================================\n';
output += '// EXÁMENES 3, 4 y 5: CIENCIA, CULTURA, RAZONAMIENTO (+' + allExams.length + ' preguntas)\n';
output += '// =============================================\n';

allExams.forEach((q, i) => {
    const id = START_ID + i;
    const opts = JSON.stringify(q.opts);
    const qText = q.q.replace(/"/g, '\\"');
    const explText = q.expl.replace(/"/g, '\\"');
    output += `{\n`;
    output += `    "id": ${id},\n`;
    output += `    "section": "${q.s}",\n`;
    output += `    "q": "${qText}",\n`;
    output += `    "visual": null,\n`;
    output += `    "opts": ${opts},\n`;
    output += `    "ans": ${q.ans},\n`;
    output += `    "expl": "${explText}",\n`;
    output += `    "context": null\n`;
    output += `},\n`;
});

// Read the file and insert before the closing ];
const filePath = path.join(__dirname, 'exaniQuestions.ts');
let content = fs.readFileSync(filePath, 'utf8');

// Find the last ]; and insert before it
const lastBracket = content.lastIndexOf('];');
if (lastBracket === -1) {
    console.error('ERROR: Could not find closing ];');
    process.exit(1);
}

content = content.slice(0, lastBracket) + output + '];\n';
fs.writeFileSync(filePath, content, 'utf8');

console.log(`✅ Insertadas ${allExams.length} preguntas (IDs ${START_ID}-${START_ID + allExams.length - 1})`);
console.log(`   Exam 3 (Ciencia): ${exam3.length}`);
console.log(`   Exam 4 (Cultura): ${exam4.length}`);
console.log(`   Exam 5 (Razonamiento): ${exam5.length}`);
